from pathlib import Path
import json,statistics,collections,gzip,csv,io
root=Path.cwd()
regions=['Floresta','Caverna','Ruinas','Pantano','Vulcao','Abismo','Fortaleza','Necropole','Citadela','Panteao','Cataclismo','Paradoxo']
names={'paladino':'Paladino','berserker':'Berserker','samurai':'Samurai','ninja':'Ninja','sniper':'Sniper','atirador_arcano':'Atirador Arcano','espreitador':'Espreitador','guarda_florestal':'Guarda Florestal','mago_incendiario':'Incendiário','mago_frigido':'Frígido','arquimago':'Arquimago','corrompido':'Corrompido','druida_sombrio':'Druida Sombrio','avatar_da_natureza':'Avatar da Natureza','fada_monarca':'Fada Monarca','protetor_da_floresta':'Protetor da Floresta'}
lines=['# Reavaliação da progressão — 06/11/2026','','192 campanhas: 16 especializações × três sementes (101, 202, 303) × antes/depois × dois cenários de equipamento. Antes usa os quatro arquivos de mecânica do commit 03e74b1; depois usa as habilidades, IA, equipamentos e crítico universais atuais. A régua continua sendo o alcance da maioria, não a obrigação de concluir o jogo.','', '## Método e limites','','Motor real do jogo, atributos equilibrados, política heurística de habilidades compartilhada entre versões. As alterações de habilidades e IA da rodada anterior já estão presentes em ambos os lados. Sem poções, torre, dungeon ou arena. Recuperação completa entre lutas. Cada derrota/fuga oferece um nível até 100; falhas repetidas melhoram uma peça. A campanha termina ao vencer o último chefe ou acumular 11 mortes já no nível 100 com seis lendários. Não mede tempo de farm nem custo real da preparação. Três sementes são uma amostra pequena, e mudanças nos críticos alteram a sequência de RNG: diferenças descritivas, sem isolamento causal de cada ajuste.','','Referência: conserva o equipamento inicial Floresta/Caverna ao melhorar, com acessório da Floresta. Conjuntos por rota: nas preparações, troca gratuitamente as peças já existentes pelo conjunto preferido liberado, preservando raridade e acessório; não cria espaços antes vazios. Essa concessão existe igualmente antes/depois e serve para comparar sinergias, não para simular economia. A escolha é pré-definida, não uma busca pelo melhor conjunto ou rotação. Ganhar poder não garante uma trajetória de RNG mais favorável.','']
summary=[]
for label,folder in [('Referência','progression-2026-11-06'),('Conjuntos por rota','progression-sets-2026-11-06')]:
 d=root/'docs/qa'/folder
 files=sorted(d.glob('*.json'));runs=[dict(json.loads(f.read_text(encoding='utf-8')),version=f.name.split('-')[0]) for f in files] if files else json.loads(gzip.decompress((d/'results.json.gz').read_bytes()))['runs']
 assert len(runs)==96,(folder,len(runs))
 lines += ['## '+label,'']
 for version in ['before','after']:
  a=[r for r in runs if r['version']==version];indices=[regions.index(r['region'])+1 for r in a]
  lines += [f"{'Antes' if version=='before' else 'Depois'}: {sum(r['fights'] for r in a)} lutas; {sum(r['deaths'] for r in a)} mortes; {sum(r['reason']=='Paradoxo derrotado' for r in a)}/48 conclusões; {sum(r['region']=='Paradoxo' for r in a)}/48 chegaram ao Paradoxo; mediana da região {statistics.median(indices)} de 12.",'']
 lines+=['| Especialização | Antes: parada (campanhas) | Depois: parada (campanhas) | Mortes medianas antes → depois | Nível final mediano depois |','|---|---|---|---:|---:|']
 def stops(a):
  c=collections.Counter('Concluiu' if r['reason']=='Paradoxo derrotado' else r['region'] for r in a)
  return '; '.join(f'{k} ({v}/3)' for k,v in c.items())
 for route,name in names.items():
  before=[r for r in runs if r['route']==route and r['version']=='before'];after=[r for r in runs if r['route']==route and r['version']=='after']
  lines.append(f"| {name} | {stops(before)} | {stops(after)} | {statistics.median(r['deaths'] for r in before)} → {statistics.median(r['deaths'] for r in after)} | {statistics.median(r['level'] for r in after)} |")
  for r in before+after:summary.append(dict(scenario=label,route=route,version=r['version'],seed=r['seed'],region=r['region'],level=r['level'],fights=r['fights'],deaths=r['deaths'],reason=r['reason']))
 lines+=['','### Gargalos após as mudanças','']
 for route,name in names.items():
  a=[r for r in runs if r['route']==route and r['version']=='after'];c=collections.Counter(x['foe']['name'] for r in a for x in r['deathEvents'])
  lines.append(f"- {name}: "+'; '.join(f'{n}: {count} derrotas' for n,count in c.most_common(3))+'.')
 lines+=['']
 # Preserve full traces compactly; runner can resume directly from these records.
 (d/'results.json.gz').write_bytes(gzip.compress(json.dumps({'baseline':'03e74b1','scenario':label,'runs':runs},ensure_ascii=False).encode(),compresslevel=9))
lines += ['## Leitura dos resultados','','Sniper e Atirador Arcano seguem acima das outras rotas nesta preparação: concluíram as três campanhas nos dois cenários depois das mudanças. O acesso universal ao crítico não eliminou essa diferença.','','Samurai segue como prioridade de investigação: duas campanhas com conjunto por rota ainda param no Panteão, e uma alcança Cataclismo; na referência, as três param no Panteão. O novo sangramento não foi suficiente para assegurar o alcance majoritário nesta política. Paladino e Berserker continuam no Cataclismo nos dois cenários.','','Incendiário deixou de ser um caso de conclusão precoce generalizada: na referência concluiu uma campanha; com a seleção pré-definida de conjuntos não concluiu nenhuma. Corrompido alcançou Paradoxo nas três campanhas de referência, mas ficou no Cataclismo nas três com conjunto por rota. Isso reforça que não se deve considerar a seleção proposta de conjuntos como otimizada.','','Frígido e Arquimago merecem revisão da rotação e da sobrevivência no Cataclismo/Panteão. Ninja tem resultados variáveis; Espreitador e Guarda Florestal chegam ao Paradoxo consistentemente sem concluir. Essa ausência de conclusão, sozinha, não justifica buffs. A linha Natureza foi executada como cobertura adicional das mudanças universais; permanece separada da prioridade de balanceamento das três linhas anteriores.','','Próxima investigação: comparar outras rotações e conjuntos para Samurai, Paladino, Berserker, Frígido e Arquimago; medir habilidade escolhida, causa da morte e HP restante do chefe. Não aumentar globalmente os equipamentos ou reduzir todos os chefes com base apenas nessas três sementes.','','## Reprodução e evidências','','- `node scripts/run-progression-2026-11-06.cjs`','- `node scripts/run-progression-sets-2026-11-06.cjs`','- Resumo: `docs/qa/progression-summary-2026-11-06.csv`.','- Evidências completas: `results.json.gz` nas duas pastas de QA, com encontros, níveis, equipamentos, mortes e uso de habilidades.']
lines += ['', '', '## Ressalva posterior sobre a política do Samurai', '', 'Ao revisar as sugestões de balanceamento, foi identificado que `warriorAction` avalia `bleedPercent`, mas não inclui `bleedMaxHpPercent` no valor esperado de Golpes Velozes. Nos três resultados atuais com conjuntos por rota, essa habilidade não foi selecionada nenhuma vez. Portanto, o bloqueio observado não demonstra que o novo sangramento de 5% é insuficiente; as conclusões sobre aumentar dano do Samurai devem ficar suspensas até corrigir a política e repetir os testes. Os resultados acima continuam sendo registros válidos da política executada, não da melhor rotação disponível.']
(root/'docs/analise_progressao_classes_2026-11-06.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
with (root/'docs/qa/progression-summary-2026-11-06.csv').open('w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(summary[0]));w.writeheader();w.writerows(summary)
print('\n'.join(lines[:14]));print('Generated 192-run report and complete compressed traces.')
